import pathlib,json,tempfile,subprocess,hashlib,tarfile,os,platform
out=pathlib.Path('docs/developer/final-acceptance/wave-04/02/workflow-dependencies');release=json.load(open(out/'actionlint-release.json'));assert platform.system()=='Darwin'and platform.machine()=='arm64';version=release['tag_name'];stem=version.removeprefix('v');archive=f'actionlint_{stem}_darwin_arm64.tar.gz';checksums=f'actionlint_{stem}_checksums.txt';assets={a['name']:a for a in release['assets']};assert archive in assets and checksums in assets
work=pathlib.Path(tempfile.mkdtemp(prefix='sgui-r25-actionlint-'));subprocess.run(['gh','release','download',version,'--repo','rhysd/actionlint','--pattern',archive,'--pattern',checksums,'--dir',str(work)],check=True)
checksumLines=(work/checksums).read_text().splitlines();matches=[s.split()[0]for s in checksumLines if s.split()[-1].lstrip('*')==archive];assert len(matches)==1;actual=hashlib.sha256((work/archive).read_bytes()).hexdigest();assert actual==matches[0]
members=[]
with tarfile.open(work/archive,'r:gz')as tar:
 for m in tar.getmembers():
  path=pathlib.PurePosixPath(m.name);assert not path.is_absolute()and'..'not in path.parts;assert m.isfile()or m.isdir();assert m.size<50_000_000;members.append({'name':m.name,'bytes':m.size,'type':'file'if m.isfile()else'directory'})
 candidates=[m for m in tar.getmembers()if m.name=='actionlint'and m.isfile()];assert len(candidates)==1;binary=work/'actionlint';binary.write_bytes(tar.extractfile(candidates[0]).read());binary.chmod(0o700)
r={'version':version,'officialRelease':release['html_url'],'metadataAPI':f'https://api.github.com/repos/rhysd/actionlint/releases/tags/{version}','platform':'darwin_arm64','archive':{'name':archive,'url':assets[archive]['browser_download_url'],'sha256':actual,'matchesOfficialChecksum':True},'officialChecksums':{'url':assets[checksums]['browser_download_url'],'sha256':hashlib.sha256((work/checksums).read_bytes()).hexdigest(),'contents':(work/checksums).read_text()},'safeArchiveMembers':members,'binary':str(binary),'binarySha256':hashlib.sha256(binary.read_bytes()).hexdigest(),'temporaryDirectory':str(work),'installScope':'Extracted one verified regular binary only to fresh task-specific temp directory; no global/system/dependency install','remoteWrites':False};(out/'actionlint-admission.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({'version':version,'binary':str(binary),'sha256':actual,'members':len(members)}))
